(()=>{const root=new URL('../',document.currentScript.src);async function load(path){return new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=new URL(path,root);s.onload=resolve;s.onerror=()=>reject(Error('공통 도구 로드 실패: '+path));document.body.append(s);});}(async()=>{await load('config.js');await load('include/collaboration.js');await load('include/spec-panel.js');await load('include/annotations.js');await load('include/message-specs.js');})().catch(e=>{const p=document.createElement('p');p.setAttribute('role','alert');p.textContent=e.message;document.body.prepend(p);});})();
